<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { onBeforeRouteLeave, useRoute } from 'vue-router'
import { listDepartments } from '@/services/iamDepartments'
import { getDepartmentWork } from '@/services/iamWork'
import { canIam, iamMessage } from '@/services/iamAccess'
import type { DepartmentSummary, WorkApp } from '@/types/iam'
import WorkSettings from '@/components/iam/WorkSettings.vue'
import EmployeeDrawer from '@/components/iam/EmployeeDrawer.vue'
const route=useRoute(),activeTab=ref('members')
const viewGroup=ref(typeof route.query.department==='string'?'all':'daily'),groupsAvailable=ref(false)
const departments=ref<DepartmentSummary[]>([]),selected=ref(''),apps=ref<WorkApp[]>([]),editingApp=ref<string|null>(null),search=ref(''),page=ref(1),loading=ref(true),error=ref(''),employeeId=ref(''),drawerOpen=ref(false)
const settings=ref<InstanceType<typeof WorkSettings>|null>(null)
const current=computed(()=>departments.value.find(row=>row.id===selected.value)),members=computed(()=>(current.value?.members||[]).filter(row=>!search.value || [row.name,row.employee_number,row.position].join(' ').toLowerCase().includes(search.value.toLowerCase())))
const tree=computed(()=>{const build=(parent:string|null):unknown[]=>departments.value.filter(row=>(row.parent_department||null)===parent || (parent===null && row.parent_department && !departments.value.some(item=>item.id===row.parent_department))).map(row=>({key:row.id,title:row.name,children:build(row.id)}));return build(null)})
const columns=[{title:'姓名 / 工号',key:'name',width:'30%'},{title:'岗位',dataIndex:'position',width:'28%'},{title:'账号状态',key:'status',width:'22%'},{title:'操作',key:'action',width:'20%'}]
async function load(){loading.value=true;error.value='';try{const data=await listDepartments(viewGroup.value);departments.value=data.items;groupsAvailable.value=data.groups_available===true;if(!departments.value.some(row=>row.id===selected.value))selected.value=departments.value[0]?.id||'';await loadApps();await applyLink()}catch(e){error.value=iamMessage(e)}finally{loading.value=false}}
async function applyLink(){
  const id=typeof route.query.department==='string'?route.query.department:''
  if(!id)return
  if(!departments.value.some(row=>row.id===id)){editingApp.value=null;activeTab.value='members';error.value='该部门或应用当前不可查看，已返回可用部门。';return}
  if(settings.value&&!await settings.value.requestLeave())return
  selected.value=id;await loadApps()
  const app=typeof route.query.app==='string'?route.query.app:''
  activeTab.value=route.query.tab==='apps'&&canIam('iam.access.read')?'apps':'members'
  editingApp.value=activeTab.value==='apps'&&apps.value.some(row=>row.app_id===app&&row.integrated)?app:null
  if(app&&!editingApp.value)error.value='该部门或应用当前不可查看，已返回可用部门。'
}
let appRead=0
async function loadApps(){const run=++appRead,id=selected.value;apps.value=[];if(canIam('iam.access.read')&&id){const result=await getDepartmentWork(id);if(run===appRead&&selected.value===id)apps.value=result.apps}}
async function select(keys:unknown[]){const id=String(keys[0]||'');if(!id||id===selected.value)return;if(settings.value&&!await settings.value.requestLeave())return;selected.value=id;editingApp.value=null;search.value='';page.value=1;try{await loadApps()}catch(e){error.value=iamMessage(e)}}
onBeforeRouteLeave(()=>settings.value?settings.value.requestLeave():true)
watch(()=>route.query,()=>{if(!loading.value)void applyLink().catch(e=>{error.value=iamMessage(e)})});
watch(viewGroup,async()=>{if(settings.value&&!await settings.value.requestLeave())return;selected.value='';editingApp.value=null;await load()});onMounted(load)
</script>
<template><section><div class="iam-heading"><div><h1>部门管理</h1><p>查看组织、主部门成员与普通应用权限。</p></div></div><a-alert v-if="error" :message="error" type="warning"/><a-skeleton v-if="loading" active/><div v-else class="department-layout"><aside class="iam-panel department-tree"><h2>组织部门</h2><a-select v-if="groupsAvailable" v-model:value="viewGroup" aria-label="部门分组" style="width:100%;margin-bottom:16px"><a-select-option value="daily">日常组织</a-select-option><a-select-option value="technical">技术验证夹具</a-select-option><a-select-option value="all">全部部门</a-select-option></a-select><a-tree :tree-data="tree" :selected-keys="[selected]" default-expand-all block-node @select="select"><template #title="{title}"><span :title="title">{{title}}</span></template></a-tree></aside><section class="iam-panel department-main"><template v-if="current"><div class="department-summary"><h2>{{current.name}}</h2><p>{{current.company}} · 主部门员工 {{current.members?.length || 0}} 人</p><a-tag v-if="!current.confirmed" color="gold">尚未确认，暂不安排人员或权限</a-tag></div><WorkSettings v-if="editingApp" ref="settings" subject-kind="department" :subject-id="selected" :app-id="editingApp" @back="editingApp=null" @saved="loadApps"/><a-tabs v-else v-model:active-key="activeTab"><a-tab-pane key="members" tab="部门成员"><div class="iam-toolbar"><a-input v-model:value="search" class="iam-search" placeholder="搜索姓名、工号或岗位" aria-label="搜索部门成员" allow-clear @change="page=1"/></div><div class="member-table"><a-table :columns="columns" :data-source="members" row-key="id" table-layout="fixed" :scroll="{x:620}" :pagination="{current:page,pageSize:10,total:members.length,showSizeChanger:false,onChange:(value:number)=>page=value}"><template #bodyCell="{column,record}"><template v-if="column.key==='name'"><button v-if="canIam('iam.people.read')" class="iam-name" :aria-label="`查看${record.name}，工号${record.employee_number}`" @click="employeeId=record.id;drawerOpen=true"><strong>{{record.name}}</strong></button><strong v-else>{{record.name}}</strong><span class="iam-code">{{record.employee_number}}</span></template><template v-else-if="column.key==='status'">{{record.account_status==='active'?'已开通':record.account_status==='disabled'?'已停用':'未开通'}}</template><template v-else-if="column.key==='action'"><a-button v-if="canIam('iam.people.read')" type="link" @click="employeeId=record.id;drawerOpen=true">查看员工</a-button><span v-else class="aux">仅成员状态</span></template></template></a-table></div><p class="aux">此处仅列主部门成员；兼岗不会自动叠加所属部门权限。</p></a-tab-pane><a-tab-pane v-if="canIam('iam.access.read')" key="apps" tab="默认应用权限"><p class="aux">部门默认权限只包含普通工作，为员工单独设置的权限保留；重要权限不会自动获得。</p><article v-for="app in apps" :key="app.app_id" class="department-app"><div><strong>{{app.title}}</strong><p>{{app.integrated?app.summary:'尚未接入此管理功能，暂不能在此调整。'}}</p></div><a-button v-if="app.integrated" :disabled="!current.confirmed" @click="editingApp=app.app_id">{{canIam('iam.departments.manage') ? '设置权限' : '查看权限'}}</a-button></article></a-tab-pane></a-tabs></template><a-empty v-else description="暂无可管理部门"/></section></div><EmployeeDrawer :open="drawerOpen" :employee-id="employeeId" @close="drawerOpen=false" @changed="load"/></section></template>
<style scoped>.department-layout{display:grid;grid-template-columns:minmax(240px,300px) minmax(0,1fr);gap:24px;align-items:start}.department-tree{min-height:520px;overflow-wrap:anywhere}.department-main{width:100%;min-width:0}.department-summary h2{font-size:22px;margin:0 0 8px;overflow-wrap:anywhere}.department-summary p{font-size:14px;color:var(--hbos-text-secondary);margin:0 0 16px}.department-tree h2{font-size:16px;margin:0 0 16px}.member-table{width:100%;min-height:280px}.department-app{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:20px 0;border-bottom:1px solid var(--hbos-border-subtle,#dde5e0)}.department-app>div{min-width:0}.department-app p{margin:8px 0 0}.department-main .iam-toolbar{width:100%}.department-tree :deep(.ant-tree-title){white-space:normal;overflow-wrap:anywhere;line-height:1.6}.department-tree :deep(.ant-tree-node-content-wrapper){min-width:0}@media(max-width:1000px){.department-layout{grid-template-columns:minmax(200px,240px) minmax(0,1fr);gap:16px}}@media(max-width:760px){.department-layout{grid-template-columns:minmax(0,1fr)}.department-tree{min-height:0}.department-app{align-items:flex-start;flex-direction:column}}</style>
